export const MEGA_CAPABLE_DEX_IDS = Object.freeze([3,6,9,15,18,26,36,65,71,80,94,115,121,127,130,142,149,150,154,160,181,208,212,214,227,229,248,254,257,260,282,302,303,306,308,310,319,323,334,354,358,359,362,373,376,380,381,382,383,384,398,428,445,448,460,475,478,485,491,500,530,531,545,560,604,609,623,652,655,658,668,670,678,687,689,691,701,718,719,740,768,780,801,807,870,952,970,978,998]);

export const MEGA_FAMILY_DEX_IDS = Object.freeze([1,2,3,4,5,6,7,8,9,13,14,15,16,17,18,25,26,35,36,63,64,65,69,70,71,79,80,92,93,94,95,115,120,121,123,127,129,130,142,147,148,149,150,152,153,154,158,159,160,172,173,179,180,181,208,212,214,227,228,229,246,247,248,252,253,254,255,256,257,258,259,260,280,281,282,302,303,304,305,306,307,308,309,310,318,319,322,323,333,334,353,354,358,359,361,362,371,372,373,374,375,376,380,381,382,383,384,396,397,398,427,428,433,443,444,445,447,448,459,460,475,478,485,491,498,499,500,529,530,531,543,544,545,559,560,602,603,604,607,608,609,622,623,650,651,652,653,654,655,656,657,658,667,668,669,670,677,678,686,687,688,689,690,691,701,718,719,739,740,767,768,780,801,807,870,951,952,969,970,978,996,997,998]);

const MEGA_CAPABLE_DEX_SET = new Set(MEGA_CAPABLE_DEX_IDS);

const MEGA_FAMILY_DEX_SET = new Set(MEGA_FAMILY_DEX_IDS);

const VALID_TYPES = new Set(["bug", "dark", "dragon", "electric", "fairy", "fighting", "fire", "flying", "ghost", "grass", "ground", "ice", "normal", "poison", "psychic", "rock", "steel", "water"]);

function cleanType(value) {
  const type = String(value || "").trim();
  return VALID_TYPES.has(type.toLocaleLowerCase()) ? type[0].toUpperCase() + type.slice(1).toLocaleLowerCase() : "";
}

export function pokemonDexIdByName(value) {
  const wanted = String(value || "").toLocaleLowerCase().replace(/[^a-z0-9♀♂]+/g, "");
  const match = Object.entries(POKEMON_NAMES).find(([, name]) => String(name).toLocaleLowerCase().replace(/[^a-z0-9♀♂]+/g, "") === wanted);
  return match ? Number(match[0]) : 0;
}

export function pokemonMoveNames(row = {}) {
  return [row.move_fast, row.move_charged_1, row.move_charged_2]
    .map(value => value == null || value === "" ? "" : MOVE_NAMES[Number(value)] || String(value).trim())
    .filter(Boolean);
}

function normalizedMoveName(value) {
  return String(value || "").toLocaleLowerCase().replace(/[’']/g, "").replace(/[^a-z0-9]+/g, " ").trim();
}

export function pokemonLegacyMoveNames(row = {}) {
  const legacy = new Set((LEGACY_MOVES_BY_DEX[Number(row.pokedex_id ?? row.dex_id)] || []).map(normalizedMoveName));
  return pokemonMoveNames(row).filter(move => legacy.has(normalizedMoveName(move)));
}

export function pokemonHasLegacyMove(row = {}) {
  return pokemonLegacyMoveNames(row).length > 0;
}

export function pokemonCanMegaEvolve(row = {}) {
  return MEGA_CAPABLE_DEX_SET.has(Number(row.pokedex_id ?? row.dex_id));
}

export function pokemonBelongsToMegaFamily(row = {}) {
  return MEGA_FAMILY_DEX_SET.has(Number(row.pokedex_id ?? row.dex_id));
}

export function pokemonTypeNames(row = {}, formLabel = "") {
  const explicit = [row.types, row.pokemon_types, row.type, row.type_1, row.type_2, row.primary_type, row.secondary_type, row.pokemon_type_1, row.pokemon_type_2]
    .flatMap(value => Array.isArray(value) ? value : value == null ? [] : String(value).split(/[,/|]/))
    .map(cleanType).filter(Boolean);
  if (explicit.length) return [...new Set(explicit)];
  const dex = Number(row.pokedex_id ?? row.dex_id);
  const regional = REGIONAL_POKEMON_TYPES[`${dex}:${String(formLabel).toLocaleLowerCase()}`];
  return [...(regional || POKEMON_TYPES[dex] || [])];
}
